import{_ as t,o as n,c as i,a2 as o}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"8.4 电动机的启动与控制","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-4-dian-dong-ji-de-qi-dong-yu-kong-zhi.md","filePath":"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-4-dian-dong-ji-de-qi-dong-yu-kong-zhi.md","lastUpdated":1793095197000}'),s={name:"electrician/low-voltage-electrician/08-chapter-8-san-xiang-yi-bu-dian-dong-ji/8-4-dian-dong-ji-de-qi-dong-yu-kong-zhi.md"};function e(l,a,r,d,g,h){return n(),i("div",null,[...a[0]||(a[0]=[o(`<h1 id="_8-4-电动机的启动与控制" tabindex="-1">8.4 电动机的启动与控制 <a class="header-anchor" href="#_8-4-电动机的启动与控制" aria-label="Permalink to &quot;8.4 电动机的启动与控制&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>电动机&quot;一转就花很大力气&quot;(启动电流大)。这一节讲怎么启动才安全——<strong>直接启动</strong>和<strong>降压启动(重点:星三角)</strong>——以及最常用的<strong>点动、自锁、正反转</strong>控制原理。这部分是理论和实操的&quot;重头戏&quot;。</p><h2 id="一、启动电流问题" tabindex="-1">一、启动电流问题 <a class="header-anchor" href="#一、启动电流问题" aria-label="Permalink to &quot;一、启动电流问题&quot;">​</a></h2><p>电动机启动瞬间,转子还没转起来、感应反电动势很小,启动电流可达额定电流的 <strong>4~7 倍</strong>:</p><ul><li>频繁启动或启动电流过大,会冲击电网、发热烧电机;</li><li>所以大电动机不能直接启动,要<strong>降压启动</strong>。</li></ul><h2 id="二、直接启动-全压启动" tabindex="-1">二、直接启动(全压启动) <a class="header-anchor" href="#二、直接启动-全压启动" aria-label="Permalink to &quot;二、直接启动(全压启动)&quot;">​</a></h2><p>直接把额定电压加到电机上启动:</p><ul><li>启动设备简单(一台断路器/接触器即可);</li><li>适用于<strong>容量较小</strong>的电动机(一般规定一定容量以下可以直接启动);</li><li>容量大、变压器容量小的地方,直接启动会引起电压明显波动。</li></ul><h2 id="三、降压启动-重点-星三角启动" tabindex="-1">三、降压启动(重点:星三角启动) <a class="header-anchor" href="#三、降压启动-重点-星三角启动" aria-label="Permalink to &quot;三、降压启动(重点:星三角启动)&quot;">​</a></h2><p>启动时先降低加在电机上的电压,减小启动电流,转速上来后再加全压。常见方法:</p><h3 id="_1-y-△-星三角-降压启动" tabindex="-1">1. Y-△(星三角)降压启动 <a class="header-anchor" href="#_1-y-△-星三角-降压启动" aria-label="Permalink to &quot;1. Y-△(星三角)降压启动&quot;">​</a></h3><p>电动机正常运行时按<strong>三角形(△)<strong>接法,启动时先接成</strong>星形(Y)</strong>,再自动切换回三角形:</p><ul><li>星形接法时,每相绕组电压只有三角形的 <strong>1/√3(约 0.577)</strong>;</li><li>启动电流减小到直接启动的 <strong>约 1/3</strong>;</li><li>启动后靠<strong>时间继电器</strong>延时,自动从 Y 切换成 △(5.6 节讲过);</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启动:接成 Y(低压启动,电流小)──延时──► 切换:接成 △(全压运行)</span></span></code></pre></div><blockquote><p>⚠️ 注意:只有<strong>铭牌标 △ 接法</strong>的电动机才适合 Y-△ 降压启动(运行本来就是 △)。</p></blockquote><h3 id="_2-自耦变压器降压启动" tabindex="-1">2. 自耦变压器降压启动 <a class="header-anchor" href="#_2-自耦变压器降压启动" aria-label="Permalink to &quot;2. 自耦变压器降压启动&quot;">​</a></h3><p>通过自耦变压器降低启动电压,启动结束后切除变压器,加全压。用于较大容量电动机。</p><h2 id="四、电动机的三种基本控制" tabindex="-1">四、电动机的三种基本控制 <a class="header-anchor" href="#四、电动机的三种基本控制" aria-label="Permalink to &quot;四、电动机的三种基本控制&quot;">​</a></h2><h3 id="_1-点动控制" tabindex="-1">1. 点动控制 <a class="header-anchor" href="#_1-点动控制" aria-label="Permalink to &quot;1. 点动控制&quot;">​</a></h3><p>按下按钮电动机转,松开就停(不保持):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按下启动按钮 → 接触器吸合 → 电动机转</span></span>
<span class="line"><span>松开按钮     → 接触器释放 → 电动机停</span></span></code></pre></div><p>用于调试、点动(如对刀)。</p><h3 id="_2-自锁-连续-控制" tabindex="-1">2. 自锁(连续)控制 <a class="header-anchor" href="#_2-自锁-连续-控制" aria-label="Permalink to &quot;2. 自锁(连续)控制&quot;">​</a></h3><p>按下启动按钮,接触器吸合后,靠<strong>接触器自身的辅助常开触点</strong>保持吸合,松开按钮电机继续转;按<strong>停止按钮</strong>才停。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启动:按启动按钮 → 接触器吸合 → 自锁触点闭合保持</span></span>
<span class="line"><span>停止:按停止按钮 → 电路断开 → 接触器释放</span></span></code></pre></div><blockquote><p>💡 通俗理解:<strong>自锁触点就是&quot;自己锁住自己&quot;</strong>——接触器用自己的一对辅助触点&quot;搂住&quot;启动按钮的回路,让按钮松开后依然通电。这是最核心的控制概念,实操必考。</p></blockquote><h3 id="_3-正反转控制" tabindex="-1">3. 正反转控制 <a class="header-anchor" href="#_3-正反转控制" aria-label="Permalink to &quot;3. 正反转控制&quot;">​</a></h3><p>电动机转向由<strong>三相电源相序</strong>决定。把任意<strong>两根相线对调</strong>,旋转磁场反向,电动机就反转:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正转:接触器 KM1(正常相序)</span></span>
<span class="line"><span>反转:接触器 KM2(对调两相)</span></span></code></pre></div><p>注意:<strong>正反转两个接触器不能同时吸合</strong>,否则会造成<strong>相间短路</strong>——必须加<strong>互锁</strong>(电气互锁或机械互锁)。</p><blockquote><p>⚠️ 判断题高频:正反转控制中,两个接触器<strong>同时通电会导致电源相间短路</strong>,必须互锁。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 启动电流为额定电流的 <strong>4~7 倍</strong>。</li><li>✅ <strong>Y-△ 降压启动</strong>:启动电流约为直接启动的 <strong>1/3</strong>,用于铭牌 △ 接法电机。</li><li>✅ <strong>自锁</strong>靠接触器自身的辅助常开触点。</li><li>✅ 正反转换相序(对调两根相线),必须<strong>互锁</strong>防止相间短路。</li><li>⚠️ 易混点:点动(松手停)vs 自锁(松手不停),区别就在有没有自锁触点。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>启动电流大(4~7 倍额定),大电机要降压启动。</li><li>星三角降压:Y 启动、△ 运行,电流降约 1/3。</li><li>点动、自锁、正反转是电动机控制三大基本功;正反转要互锁。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)三相异步电动机启动瞬间,启动电流可达额定电流的()倍。 A. 1~2　B. 4~7　C. 10~20　D. 0.5~1</li><li>(判断)Y-△ 降压启动,是把启动电流降到直接启动的约 1/3。( )</li><li>(单选)自锁控制中,使电动机在松开按钮后仍能继续运转的关键元件是()。 A. 接触器辅助常开触点　B. 按钮　C. 热继电器　D. 熔断器</li><li>(判断)正反转控制中,正转和反转两个接触器可以同时吸合。( )</li><li>(单选)电动机要反转,最简单的方法是()。 A. 调低电压　B. 对调两根相线　C. 减小负载　D. 换大电机</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。启动电流为额定电流的 4~7 倍。</li><li><strong>√</strong>。星形接法电压降至 1/√3,启动电流约为直接启动的 1/3。</li><li><strong>A</strong>。接触器自身辅助常开触点起自锁作用。</li><li><strong>×</strong>。同时吸合会造成相间短路,必须互锁。</li><li><strong>B</strong>。对调任意两根相线,电动机即反转。</li></ol></details>`,39)])])}const u=t(s,[["render",e]]);export{c as __pageData,u as default};
